#include <bits/stdc++.h>

using namespace std;

const int MOD_CONST = 1000000007;
int n, m, answer_value, visited_array[1048576];

int process() {
    answer_value = 1;
    if (m == 0) {
        for (int i = 1; i < n; ++i) {
            answer_value = (long long)answer_value * n % MOD_CONST;
        }
    } else if (m == 1) {
        for (int i = 1; i <= n; ++i) {
            answer_value = (long long)answer_value * n % MOD_CONST;
        }
    } else {
        for (int i = 0; i < n; ++i) {
            if (!visited_array[i]) {
                int cycle_size = 0;
                int idx = i;
                while (!visited_array[idx]) {
                    visited_array[idx] = 1;
                    ++cycle_size;
                    idx = (long long)idx * m % n;
                }
                if (idx != 0) {
                    answer_value = (long long)answer_value * n % MOD_CONST;
                }
            }
        }
    }
    return answer_value;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("data", "r", stdin);
#endif
    cin >> n >> m;
    cout << process();
}
